import { expect, test } from "@playwright/test";

test.describe("Trail Runner 2 product page", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/products/trail-runner-2");
  });

  test("shows the Stride store and cart count", async ({ page }) => {
    const header = page.locator("header");
    await expect(header).toContainText("Stride");
    await expect(header).toContainText(/cart/i);
    await expect(header).toContainText(/\d+/);
  });

  test("shows a navigable path with links to earlier locations", async ({ page }) => {
    await expect(page.getByText("Shop", { exact: true })).toBeVisible();
    await expect(page.locator("a", { hasText: "Trail" })).toBeVisible();
    await expect(page.getByText("Trail Runner 2", { exact: true }).first()).toBeVisible();

    await page.locator("a", { hasText: "Trail" }).first().click();
    await expect(page).not.toHaveURL(/\/products\/trail-runner-2$/);
  });

  test("shows one shoe photo and cycles next and previous with wraparound", async ({ page }) => {
    const photo = page.locator("img").first();
    const next = page.locator("button", { hasText: /next|→|›/i });
    const previous = page.locator("button", { hasText: /prev|←|‹/i });

    await expect(photo).toBeVisible();
    const firstPhoto = await photo.getAttribute("src");

    await next.click();
    await expect(photo).not.toHaveAttribute("src", firstPhoto);

    await previous.click();
    await expect(photo).toHaveAttribute("src", firstPhoto);

    await previous.click();
    await expect(photo).not.toHaveAttribute("src", firstPhoto);
  });

  test("shows the price and explains that it includes taxes", async ({ page }) => {
    await expect(page.getByText(/\$\d+(?:\.\d{2})?/).first()).toBeVisible();

    await expect(page.getByText(/includes taxes/i)).toBeHidden();
    await page.locator("button", { hasText: /^(i|info|ⓘ|ℹ️)$/i }).first().hover();
    await expect(page.getByText(/includes taxes/i)).toBeVisible();
  });

  test("allows choosing between blue, black, and grey", async ({ page }) => {
    for (const color of ["Blue", "Black", "Grey"]) {
      await expect(page.getByText(color, { exact: true })).toBeVisible();
    }

    await page.getByText("Black", { exact: true }).click();
    await expect(page.getByText(/color: black/i)).toBeVisible();

    await page.getByText("Blue", { exact: true }).click();
    await expect(page.getByText(/color: blue/i)).toBeVisible();
  });

  test("opens a size picker, shows only the selected size, and excludes sold-out sizes", async ({
    page,
  }) => {
    const sizePicker = page.locator("button", { hasText: /^Size(?! guide)/ }).first();
    const before = await sizePicker.textContent();
    await sizePicker.click();

    await expect(page.getByText(/sold out/i).first()).toBeVisible();
    await page.getByText(/sold out/i).first().click({ force: true, timeout: 2_000 }).catch(() => {});
    await expect(sizePicker).toHaveText(before);

    await page.getByText("US 10", { exact: true }).click();
    await expect(sizePicker).toContainText("10");
    await expect(page.getByText("US 11", { exact: true })).toBeHidden();
  });

  test("opens the size guide, calculates a size by foot length and unit, and must be closed", async ({
    page,
  }) => {
    await page.locator("button", { hasText: /size guide/i }).click();
    await expect(page.getByText(/foot length|size chart/i).first()).toBeVisible();

    await page.locator("input").first().fill("26");
    await page.locator("button", { hasText: /get|find|calculate/i }).click();
    await expect(page.getByText(/\b(US|EU)\s*\d+/).first()).toBeVisible();

    await page.locator("button", { hasText: /close/i }).click();
    await expect(page.getByText(/foot length|size chart/i).first()).toBeHidden();
  });

  test("changes quantity by typing and by one-item controls", async ({ page }) => {
    const quantity = page.locator("input").first();
    await expect(quantity).toHaveValue("1");

    await page.locator("button", { hasText: "+" }).click();
    await expect(quantity).toHaveValue("2");
    await page.locator("button", { hasText: "-" }).click();
    await expect(quantity).toHaveValue("1");

    await quantity.fill("3");
    await expect(quantity).toHaveValue("3");
  });

  test("requires a size before adding the shoe and confirms a successful add", async ({ page }) => {
    const header = page.locator("header");
    const addToCart = page.locator("button", { hasText: /add to cart/i });

    await addToCart.click();
    await expect(page.getByText(/choose|select|pick/i).first()).toBeVisible();

    await page.locator("button", { hasText: /^Size(?! guide)/ }).first().click();
    await page.getByText("US 10", { exact: true }).click();
    await addToCart.click();

    await expect(page.getByText(/added/i).first()).toBeVisible();
    await expect(header).toContainText("1");
  });

  test("toggles the shoe in and out of the wishlist", async ({ page }) => {
    const wishlist = page.locator("button", { hasText: /wishlist|favorite|heart|save/i }).first();

    const before = await wishlist.innerHTML();
    await wishlist.click();
    await expect.poll(() => wishlist.innerHTML()).not.toBe(before);
    await wishlist.click();
    await expect.poll(() => wishlist.innerHTML()).toBe(before);
  });

  test("shows one of details, reviews, and shipping at a time", async ({ page }) => {
    const seen = [];
    for (const section of ["Details", "Reviews", "Shipping"]) {
      await page.getByText(section, { exact: true }).first().click();
      const content = await page.locator("main").innerText();
      expect(seen).not.toContain(content);
      seen.push(content);
    }
  });

  test("reveals an answer when a common question is opened", async ({ page }) => {
    const visibleTextBefore = await page.locator("body").innerText();

    await page.locator("button", { hasText: /\?/ }).first().click();

    const visibleTextAfter = await page.locator("body").innerText();
    expect(visibleTextAfter.length).toBeGreaterThan(visibleTextBefore.length);
  });

  test("shows customer help, company, and social links at the bottom", async ({ page }) => {
    const footer = page.locator("footer");
    await footer.scrollIntoViewIfNeeded();

    await expect(footer).toContainText(/customer help/i);
    await expect(footer).toContainText(/company/i);
    await expect(footer.locator("a").first()).toBeVisible();
    expect(await footer.locator("a").count()).toBeGreaterThanOrEqual(3);
  });
});

