import { useState } from 'react'

// One photo at a time; next/previous wrap around at the ends.
export default function PhotoCarousel({ photos, label }) {
  const [index, setIndex] = useState(0)
  const count = photos.length
  const photo = photos[index]

  const show = (i) => setIndex(((i % count) + count) % count)

  return (
    <section className="gallery" aria-roledescription="carousel" aria-label={label}>
      <div className="gallery__stage">
        <img className="gallery__image" src={photo.src} alt={photo.alt} width="800" height="500" />
      </div>
      <div className="gallery__controls">
        <button type="button" className="icon-button" aria-label="Previous photo" onClick={() => show(index - 1)}>
          ‹
        </button>
        <p className="gallery__count" aria-live="polite">
          Photo {index + 1} of {count}
        </p>
        <button type="button" className="icon-button" aria-label="Next photo" onClick={() => show(index + 1)}>
          ›
        </button>
      </div>
    </section>
  )
}
EOF

