// APG radio group: one checked option, arrow keys move and check.
export default function ColorPicker({ colors, value, onChange, labelId }) {
  const buttons = useRef([])

  const choose = (index) => {
    const next = colors[(index + colors.length) % colors.length]
    onChange(next.id)
    buttons.current[colors.indexOf(next)]?.focus()
  }

  const onKeyDown = (event, index) => {
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowDown':
        event.preventDefault()
        choose(index + 1)
        break
      case 'ArrowLeft':
      case 'ArrowUp':
        event.preventDefault()
        choose(index - 1)
        break
      default:
        break
    }
  }

  return (
    <div role="radiogroup" aria-labelledby={labelId} className="swatches">
      {colors.map((color, index) => {
        const checked = color.id === value
        return (
          <button
            key={color.id}
            ref={(el) => (buttons.current[index] = el)}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            className="swatch-option"
            onClick={() => onChange(color.id)}
            onKeyDown={(event) => onKeyDown(event, index)}
          >
            <span
              className={checked ? 'swatch swatch--checked' : 'swatch'}
              style={{ backgroundColor: color.hex }}
              aria-hidden="true"
            >
