import { useEffect, useId, useRef, useState } from 'react'

// Button that opens a listbox (APG select-only pattern). The list only exists while open.
export default function SizePicker({ sizes, value, onChange, describedBy }) {
  const [open, setOpen] = useState(false)
  const buttonRef = useRef(null)
  const rootRef = useRef(null)
  const optionRefs = useRef([])
  const listboxId = useId()
  const enabledIndexes = sizes.map((s, i) => (s.soldOut ? -1 : i)).filter((i) => i >= 0)

  const close = (restoreFocus) => {
    setOpen(false)
    if (restoreFocus) buttonRef.current?.focus()
  }

  // Focus the selected option (or the first available one) when the list opens.
  useEffect(() => {
    if (!open) return
    const selectedIndex = sizes.findIndex((s) => s.us === value?.us)
    const start = selectedIndex >= 0 && !sizes[selectedIndex].soldOut ? selectedIndex : enabledIndexes[0]
    optionRefs.current[start]?.focus()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open])

  // Close when the pointer goes down outside the picker.
  useEffect(() => {
    if (!open) return
    const onPointerDown = (event) => {
      if (!rootRef.current?.contains(event.target)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  const select = (size) => {
    if (size.soldOut) return
    onChange(size)
    close(true)
  }

  const moveFocus = (fromIndex, step) => {
    const pos = enabledIndexes.indexOf(fromIndex)
    const next = enabledIndexes[(pos + step + enabledIndexes.length) % enabledIndexes.length]
    optionRefs.current[next]?.focus()
  }

  const onListKeyDown = (event, index) => {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        moveFocus(index, 1)
        break
      case 'ArrowUp':
        event.preventDefault()
        moveFocus(index, -1)
        break
      case 'Home':
        event.preventDefault()
        optionRefs.current[enabledIndexes[0]]?.focus()
        break
      case 'End':
        event.preventDefault()
        optionRefs.current[enabledIndexes[enabledIndexes.length - 1]]?.focus()
        break
      case 'Enter':
      case ' ':
        event.preventDefault()
        select(sizes[index])
        break
      case 'Escape':
        event.preventDefault()
        close(true)
        break
      case 'Tab':
        setOpen(false)
        break
      default:
        break
    }
  }

  return (
    <div className="size-picker" ref={rootRef}>
      <button
        ref={buttonRef}
        type="button"
        className="select-button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listboxId : undefined}
        aria-describedby={describedBy}
        onClick={() => setOpen((o) => !o)}
        onKeyDown={(event) => {
          if (event.key === 'ArrowDown' && !open) {
            event.preventDefault()
            setOpen(true)
          }
        }}
      >
        {value ? `Size: US ${value.us} (EU ${value.eu})` : 'Size: Select a size'}
      </button>

      {open && (
        <ul id={listboxId} role="listbox" aria-label="Size" className="listbox">
          {sizes.map((size, index) => {
            const selected = value?.us === size.us
            return (
              <li
                key={size.us}
                ref={(el) => (optionRefs.current[index] = el)}
                role="option"
                aria-selected={selected}
                aria-disabled={size.soldOut ? 'true' : undefined}
                tabIndex={size.soldOut ? -1 : 0}
                className={[
                  'listbox__option',
                  selected ? 'listbox__option--selected' : '',
                  size.soldOut ? 'listbox__option--soldout' : '',
                ].join(' ')}
                onClick={() => select(size)}
                onKeyDown={(event) => onListKeyDown(event, index)}
              >
                <span>US {size.us}</span>
                <span className="listbox__eu">EU {size.eu}</span>
                {size.soldOut && <span className="listbox__status">Sold out</span>}
              </li>
            )
          })}
        </ul>
      )}
    </div>
  )
}
