import { useEffect, useId, useRef, useState } from 'react'

const FOCUSABLE = 'button, input, select, textarea, a[href], [tabindex]:not([tabindex="-1"])'

// Modal dialog (APG dialog pattern). Focus is kept inside, Escape or Close dismisses it.
export default function SizeGuideDialog({ chart, range, onClose }) {
  const titleId = useId()
  const inputId = useId()
  const hintId = useId()
  const errorId = useId()
  const dialogRef = useRef(null)
  const inputRef = useRef(null)
  const [footText, setFootText] = useState('')
  const [unit, setUnit] = useState('us')
  const [footCm, setFootCm] = useState(null)
  const [error, setError] = useState('')

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const rowFor = (cm) => chart.find((row) => cm < row.max) ?? chart[chart.length - 1]
  const row = footCm === null ? null : rowFor(footCm)

  const onSubmit = (event) => {
    event.preventDefault()
    const cm = Number.parseFloat(footText)
    if (!Number.isFinite(cm) || cm < range.min || cm > range.max) {
      setError(`Enter a foot length between ${range.min} and ${range.max} cm.`)
      setFootCm(null)
      inputRef.current?.focus()
      return
    }
    setError('')
    setFootCm(cm)
  }

  const onKeyDown = (event) => {
    if (event.key === 'Escape') {
      event.preventDefault()
      onClose()
      return
    }
    if (event.key !== 'Tab') return
    const items = [...dialogRef.current.querySelectorAll(FOCUSABLE)].filter((el) => !el.disabled)
    const first = items[0]
    const last = items[items.length - 1]
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault()
      last.focus()
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault()
      first.focus()
    }
  }

  const sizeText = row && (unit === 'us' ? `US ${row.us} (EU ${row.eu})` : `EU ${row.eu} (US ${row.us})`)

  return (
    <div className="dialog-backdrop">
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="dialog"
        onKeyDown={onKeyDown}
      >
        <div className="dialog__header">
          <h2 id={titleId}>Size chart</h2>
          <button type="button" className="text-button" onClick={onClose}>
            Close
          </button>
        </div>

        <table className="size-table">
          <thead>
            <tr>
              <th scope="col">Foot length (cm)</th>
              <th scope="col">US</th>
              <th scope="col">EU</th>
            </tr>
          </thead>
          <tbody>
            {chart.map((r) => (
              <tr key={r.us}>
                <td>
                  {r.min.toFixed(1)} to {r.max.toFixed(1)}
                </td>
                <td>{r.us}</td>
                <td>{r.eu}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <form className="size-finder" onSubmit={onSubmit} noValidate>
          <div className="field">
            <label htmlFor={inputId}>Foot length (cm)</label>
            <p id={hintId} className="hint">
              Measure from your heel to your longest toe.
            </p>
            <input
              ref={inputRef}
              id={inputId}
              type="number"
              inputMode="decimal"
              step="0.1"
              min={range.min}
              max={range.max}
              value={footText}
              onChange={(event) => setFootText(event.target.value)}
              aria-describedby={error ? `${hintId} ${errorId}` : hintId}
              aria-invalid={error ? 'true' : undefined}
            />
          </div>

          <fieldset className="field">
            <legend>Show my size in</legend>
            <label className="inline-option">
              <input type="radio" name={`unit-${titleId}`} value="us" checked={unit === 'us'} onChange={() => setUnit('us')} />
              US
            </label>
            <label className="inline-option">
              <input type="radio" name={`unit-${titleId}`} value="eu" checked={unit === 'eu'} onChange={() => setUnit('eu')} />
              EU
            </label>
          </fieldset>

          <p id={errorId} className="field-error" role="alert">
            {error}
          </p>

          <button type="submit" className="button button--secondary">
            Get my size
          </button>
          <p className="result" role="status">
            {sizeText && <>Your size: {sizeText}</>}
          </p>
        </form>
      </div>
    </div>
  )
}
