import { useId, useRef, useState } from 'react'

// APG tabs: Details, Reviews and Shipping sit side by side; one panel is shown at a time.
export default function ProductTabs({ details, reviews, shipping }) {
  const baseId = useId()
  const tabs = [
    { key: 'details', label: 'Details' },
    { key: 'reviews', label: 'Reviews' },
    { key: 'shipping', label: 'Shipping' },
  ]
  const [selected, setSelected] = useState('details')
  const tabRefs = useRef({})

  const select = (key) => {
    setSelected(key)
    tabRefs.current[key]?.focus()
  }

  const onKeyDown = (event, index) => {
    let nextIndex = null
    if (event.key === 'ArrowRight') nextIndex = (index + 1) % tabs.length
    if (event.key === 'ArrowLeft') nextIndex = (index - 1 + tabs.length) % tabs.length
    if (event.key === 'Home') nextIndex = 0
    if (event.key === 'End') nextIndex = tabs.length - 1
    if (nextIndex === null) return
    event.preventDefault()
    select(tabs[nextIndex].key)
  }

  return (
    <section className="more-info" aria-labelledby={`${baseId}-title`}>
      <h2 id={`${baseId}-title`}>More information</h2>
      <div role="tablist" aria-label="More information" className="tablist">
        {tabs.map((tab, index) => {
          const isSelected = selected === tab.key
          return (
            <button
              key={tab.key}
              ref={(el) => {
                tabRefs.current[tab.key] = el
              }}
              type="button"
              role="tab"
              id={`${baseId}-${tab.key}-tab`}
              aria-selected={isSelected}
              aria-controls={`${baseId}-${tab.key}-panel`}
              tabIndex={isSelected ? 0 : -1}
              className={isSelected ? 'tab tab--selected' : 'tab'}
              onClick={() => select(tab.key)}
              onKeyDown={(event) => onKeyDown(event, index)}
            >
              {tab.label}
            </button>
          )
        })}
      </div>

      <div
        role="tabpanel"
        id={`${baseId}-details-panel`}
        aria-labelledby={`${baseId}-details-tab`}
        hidden={selected !== 'details'}
        tabIndex={0}
        className="tabpanel"
      >
        <p>{details.intro}</p>
        <ul>
          {details.features.map((feature) => (
            <li key={feature}>{feature}</li>
          ))}
        </ul>
        <p>{details.weight}</p>
        <p>{details.drop}</p>
      </div>

      <div
        role="tabpanel"
        id={`${baseId}-reviews-panel`}
        aria-labelledby={`${baseId}-reviews-tab`}
        hidden={selected !== 'reviews'}
        tabIndex={0}
        className="tabpanel"
      >
        <p className="rating">
          Rated {reviews.average} out of 5 from {reviews.count} reviews
        </p>
        <ul className="review-list">
          {reviews.items.map((review) => (
            <li key={review.author}>
              <p>
                <strong>{review.author}</strong>, {review.rating} out of 5
              </p>
              <p>{review.text}</p>
            </li>
          ))}
        </ul>
      </div>

      <div
        role="tabpanel"
        id={`${baseId}-shipping-panel`}
        aria-labelledby={`${baseId}-shipping-tab`}
        hidden={selected !== 'shipping'}
        tabIndex={0}
        className="tabpanel"
      >
        <p>{shipping.intro}</p>
        <ul>
          {shipping.lines.map((line) => (
            <li key={line}>{line}</li>
          ))}
        </ul>
      </div>
    </section>
  )
}
