                  </button>
                </div>
                <p id={sizeErrorId} className="field-error" role="alert">
                  {sizeError}
                </p>
              </div>

              <div className="option-group">
                <label htmlFor={quantityId} className="option-label">
                  Quantity
                </label>
                <div className="quantity">
                  <button
                    type="button"
                    className="icon-button"
                    aria-label="Decrease quantity"
                    disabled={quantity <= MIN_QUANTITY}
                    onClick={() => setQuantityText(String(Math.max(MIN_QUANTITY, quantity - 1)))}
                  >
                    -
                  </button>
                  <input
                    id={quantityId}
                    type="number"
                    inputMode="numeric"
                    min={MIN_QUANTITY}
                    max={max}
                    value={quantityText}
                    onChange={(event) => setQuantityText(event.target.value)}
                    onBlur={() => setQuantityText(String(quantity))}
                    aria-describedby={`${quantityId}-hint`}
                  />
                  <button
                    type="button"
                    className="icon-button"
                    aria-label="Increase quantity"
                    disabled={quantity >= max}
                    onClick={() => setQuantityText(String(Math.min(max, quantity + 1)))}
                  >
                    +
                  </button>
                </div>
                <p id={`${quantityId}-hint`} className="hint">
                  Up to {max} pairs per order.
                </p>
              </div>

              <div className="actions">
                <button type="button" className="button button--primary" onClick={addToCart}>
                  Add to cart
                </button>
                <WishlistButton saved={saved} onToggle={() => setSaved((s) => !s)} />
              </div>

              <p className="status" role="status">
                {status}
              </p>
            </div>
          </div>

          <ProductTabs details={product.details} reviews={product.reviews} shipping={product.shipping} />
          <FaqList items={product.faqs} />
        </main>

        <SiteFooter />
      </div>
    </>
  )
}
